target.css:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #f5c842;
  --accent-soft: #ffe899;
  --text-main: #f0e6c8;
  --text-muted: #8a8fad;
  --border: #f5c842;
  --footer-bg: #0f3460;
  --badge-text: #1a1a2e;
}

.jar-tag {
  background-color: var(--card-bg);
  border: 2px solid var(--border);
  border-radius: 16px;
  width: 260px;
  padding: 0;
  overflow: hidden;
  margin: 40px auto;
}

.tag-header {
  background-color: var(--bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 20px;
  border-bottom: 1px solid var(--border);
}

.firefly-icon {
  font-size: 26px;
  line-height: 1;
}

.tag-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--accent);
  margin: 0;
  letter-spacing: 0.04em;
}

.tag-body {
  padding: 16px 20px;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 14px;
  align-items: baseline;
}

.tag-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin: 0;
}

.tag-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-main);
  margin: 0;
}

.tag-footer {
  background-color: var(--footer-bg);
  border-top: 1px solid var(--border);
  padding: 10px 20px;
  text-align: center;
}

.rule-badge {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-soft);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
